<?php

namespace LaraSlice\Tests\Feature\Core;

use LaraSlice\Core\Discovery\SliceManager;
use LaraSlice\Tests\TestCase;

class SliceRepairTest extends TestCase
{
    private string $slicePath;

    private string $legacyView;

    protected function setUp(): void
    {
        parent::setUp();

        // A slice generated by an older version, with a view layout the repair upgrades
        $this->slicePath = config('laraslice.slices_path').DIRECTORY_SEPARATOR.'LegacyNotes';
        @mkdir($this->slicePath.'/Resources/views', 0755, true);
        file_put_contents($this->slicePath.'/slice.json', json_encode(['name' => 'LegacyNotes', 'active' => true]));
        $this->legacyView = $this->slicePath.'/Resources/views/form.blade.php';
        file_put_contents($this->legacyView, '<div class="max-w-2xl mx-auto space-y-6">form</div>');
    }

    protected function tearDown(): void
    {
        app('files')->deleteDirectory($this->slicePath);
        parent::tearDown();
    }

    public function test_discovering_slices_never_writes_files(): void
    {
        $before = file_get_contents($this->legacyView);

        app(SliceManager::class)->discover();

        $this->assertSame($before, file_get_contents($this->legacyView));
    }

    public function test_repair_command_updates_legacy_files_only_when_asked(): void
    {
        $this->artisan('slice:repair', ['slice' => 'LegacyNotes', '--dry-run' => true])
            ->expectsOutputToContain('would update')
            ->assertSuccessful();
        $this->assertStringContainsString('max-w-2xl', file_get_contents($this->legacyView));

        $this->artisan('slice:repair', ['slice' => 'LegacyNotes'])->assertSuccessful();
        $this->assertStringContainsString('w-full max-w-5xl mx-auto space-y-6', file_get_contents($this->legacyView));

        $this->artisan('slice:repair', ['slice' => 'LegacyNotes'])
            ->expectsOutputToContain('up to date')
            ->assertSuccessful();
    }

    public function test_core_package_slices_are_never_repaired(): void
    {
        $users = app(SliceManager::class)->getSlice('Users');

        $this->assertSame([], app(SliceManager::class)->repairSlice($users));
    }

    public function test_remap_nav_does_not_crash_on_undefined_changed(): void
    {
        // Regression (a916eef): $changed was used before initialization when
        // --remap-nav was passed, causing "Undefined variable $changed".
        // The command must complete without crashing.

        // Create a test slice with an old-style navigation group
        $testPath = config('laraslice.slices_path').DIRECTORY_SEPARATOR.'TestRemap';
        @mkdir($testPath, 0755, true);
        file_put_contents($testPath.'/slice.json', json_encode([
            'name' => 'TestRemap',
            'navigation' => ['group' => 'OldGroup', 'label' => 'Test'],
            'models' => [['table' => 'tasks']],
        ]));

        try {
            $this->artisan('slice:repair', ['--remap-nav' => true, '--no-interaction' => true])
                ->assertSuccessful();
        } finally {
            app('files')->deleteDirectory($testPath);
        }
    }

    public function test_remap_nav_assigns_demo_aligned_module_groups(): void
    {
        // Regression: remap-nav should assign demo-aligned groups (Work, Finance, etc.)
        // not engineering labels (FinancialAccounting, Operations).
        $testPath = config('laraslice.slices_path').DIRECTORY_SEPARATOR.'TestTasks';
        @mkdir($testPath, 0755, true);
        file_put_contents($testPath.'/slice.json', json_encode([
            'name' => 'TestTasks',
            'navigation' => ['group' => 'ERP', 'label' => 'Test Tasks'],
            'models' => [['table' => 'tasks']],
        ]));

        try {
            $this->artisan('slice:repair', ['slice' => 'TestTasks', '--remap-nav' => true, '--no-interaction' => true])
                ->assertSuccessful();

            $manifest = json_decode(file_get_contents($testPath.'/slice.json'), true);
            // Tasks should map to Work, not ERP or FinancialAccounting
            $this->assertEquals('Work', $manifest['navigation']['group']);
        } finally {
            app('files')->deleteDirectory($testPath);
        }
    }
}
